// === Tab: mySketch ===
var data, traits, voice;
var hu;
let particles = [];
let osc, envelope, fft, word, rhy,animal;

let scaleArray = [62, 64, 65, 67, 69, 71, 72, 75, 77, 88];
let note = 0;


function preload() 
{
  data = loadJSON('https://openprocessing.org/sketch/1845132/files/personality.json');
}


function setup() 
{
   createCanvas(1112, 834);
	 colorMode(HSB);
	 hu = random(360);
   background(hu, 30, 100);
   traits = data['personality']
   textFont('Georgia');   
	 voice = new p5.Speech(floor(random(22)));
	 voice.interrupt = true;

  osc = new p5.SinOsc();

  // Instantiate the envelope
  envelope = new p5.Env();

  // set attackTime, decayTime, sustainRatio, releaseTime
  envelope.setADSR(0.001, 0.5, 0.1, 0.5);

  // set attackLevel, releaseLevel
  envelope.setRange(1, 0);
  rectMode(CENTER);
  cursor(CROSS);
	textSize(width/35)
  current = 'CLICK TO START';
  text(current,width/2-textWidth(current)/2,height/2);
}

function mouseClicked()
{
  clear();
	 hu = random(360);
   background(hu, 30, 100);

	current = traits[int(random(traits.length))]

	voice.setVoice(int(random(28)));

	voice.speak(current);

  textSize(width/35)

  text(current,width/2-textWidth(current)/2,height/2);

  particles.push(new Particle(random(width),random(height),current))

}


function draw() {
    for(let particle of particles){

    particle.edges();


    var wind = createVector(5,0);

    if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
      particle.applyForce(wind);
    }

    particle.update();

    particle.display();

    }


}


class Particle {
  constructor(x, y, txt){
    this.pos = createVector(x, y);
    this.vel = createVector(0.7,0.7);
    this.vel.mult(12);
		this.txt = txt;
		this.currentTime = second();

		this.timeExisted = 0;

    this.r = textWidth(this.txt)/2;
    this.acc = createVector(0, 0);

  }

  applyForce(force) {
    this.acc.add(force);


  }

  update(){
    this.vel.add(this.acc);
    this.pos.add(this.vel);

    this.acc.set(0, 0);

		this.timeExisted = second();



		if(abs(this.currentTime-this.timeExisted)>5){
			particles.shift();
			clear();
	    hu = random(360);
      background(hu, 30, 100);
		}

  }

  display(){
		textAlign(CENTER);

    if(this.pos.y>=height-this.r-10){


      strokeWeight(0.75);
      stroke(0);


      text(this.txt, this.pos.x, this.pos.y);



    }else {

    fill(22);
    stroke(222);
    strokeWeight(3);

		text(this.txt, this.pos.x, this.pos.y);


    }
  }



  edges(){


    if(this.pos.y>=height - this.r-10){
      this.pos.y = height-this.r-10;

       mus();



      this.vel.y *= -1;

    }
    else if (this.pos.x >= width-this.r){
      mus();
      this.pos.x = width-this.r;
      this.vel.x *= -1;
      } else if (this.pos.x <=this.r){
        mus();
        this.pos.x = this.r;
        this.vel.x *= -1;
      } else if (this.pos.y<= this.r){
        mus();
        this.pos.y = this.r;
        this.vel.y *= -1;
      } 
  }
}


function mus(){
	 let midiValue = scaleArray[note];
    let freqValue = midiToFreq(midiValue*random(0.5,0.9));
    osc.freq(freqValue);
    osc.start();

    envelope.play(osc, 0, 0.1);
    note = (note + 1) % scaleArray.length;  
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

